questionvariables.text:
vlist: [
  [1, [["a", "A", "B"], ["b", "A", "B"], ["c", "A", "B"]], "two areas of land, A and B", 3, 4, false, "A and B each have 3 bridges, so each appears \\(\\dfrac{3 + 1}{2} = 2\\) times", "2 + 2", "start in A and cross a, b and c in turn, giving the list A, B, A, B"],
  [2, [["a", "A", "B"], ["b", "A", "B"], ["c", "A", "B"], ["d", "A", "B"], ["e", "A", "B"]], "two areas of land, A and B", 5, 6, false, "A and B each have 5 bridges, so each appears \\(\\dfrac{5 + 1}{2} = 3\\) times", "3 + 3", "start in A and cross a, b, c, d and e in turn, giving the list A, B, A, B, A, B"],
  [3, [["a", "A", "B"], ["b", "A", "C"], ["c", "A", "D"], ["d", "B", "C"], ["e", "B", "D"], ["f", "C", "D"]], "four areas of land, A, B, C and D", 6, 8, true, "A, B, C and D each have 3 bridges, so each appears \\(\\dfrac{3 + 1}{2} = 2\\) times", "2 + 2 + 2 + 2", ""],
  [4, [["a", "A", "B"], ["b", "A", "C"], ["c", "A", "D"], ["d", "B", "C"], ["e", "B", "C"]], "four areas of land, A, B, C and D", 5, 7, true, "A, B and C each have 3 bridges, so each appears \\(\\dfrac{3 + 1}{2} = 2\\) times, and D has 1 bridge, so it appears \\(\\dfrac{1 + 1}{2} = 1\\) time", "2 + 2 + 2 + 1", ""],
  [5, [["a", "A", "B"], ["b", "A", "B"], ["c", "A", "C"], ["d", "A", "C"], ["e", "A", "D"], ["f", "B", "C"], ["g", "B", "C"], ["h", "B", "D"], ["i", "C", "D"]], "four areas of land, A, B, C and D", 9, 11, true, "A, B and C each have 5 bridges, so each appears \\(\\dfrac{5 + 1}{2} = 3\\) times, and D has 3 bridges, so it appears \\(\\dfrac{3 + 1}{2} = 2\\) times", "3 + 3 + 3 + 2", ""],
  [6, [["a", "A", "B"], ["b", "A", "B"], ["c", "A", "B"], ["d", "A", "C"], ["e", "A", "D"], ["f", "B", "C"], ["g", "B", "D"], ["h", "C", "D"]], "four areas of land, A, B, C and D", 8, 10, true, "A and B each have 5 bridges, so each appears \\(\\dfrac{5 + 1}{2} = 3\\) times, and C and D each have 3 bridges, so each appears \\(\\dfrac{3 + 1}{2} = 2\\) times", "3 + 3 + 2 + 2", ""]];
vrec: rand(vlist);
vnum: vrec[1];
blist: vrec[2];
areastxt: vrec[3];
nE: vrec[4];
tot: vrec[5];
contra: vrec[6];
perarea: vrec[7];
sumtxt: vrec[8];
routetxt: vrec[9];
nL: nE + 1;
tE: 2*nE;
tfl: [2, 4, 4, 3, 7, 6][vnum];
ta3: if contra then [[cy, true, "Yes"], [cn, false, "No"]] else [[cy, false, "Yes"], [cn, true, "No"]];
s_assert(is(nE = length(blist)), true);
s_assert(is(contra = is(tot > nL)), true);
